with base as (select *, upper(city) as city_upper from suppliers where rating > 3.5) select case when rating >= 3.9 then 'PREMIUM' else 'STANDARD' end as rating_tier, stddev_samp(rating) as rating_stddev, size(collect_set(country)) as num_countries, count(distinct id) as distinct_ids, round(sum(rating) / nullif(count(case when country = 'US' then 1 end), 0), 2) as rating_per_us, sort_array(collect_set(country)) as country_list, sort_array(collect_set(city)) as city_list from base group by case when rating >= 3.9 then 'PREMIUM' else 'STANDARD' end;
